import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,o as n,c as r,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Funzionalità scansione NFC","description":"","frontmatter":{"source_hash":"256676a54d","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/NFC.md","filePath":"it/use/NFC.md"}'),p={name:"it/use/NFC.md"};function d(c,e,m,u,h,b){return n(),r("div",null,[...e[0]||(e[0]=[l('<p>Questo menu compare solo se è selezionata una <a href="./../install/datasource.html#libre">sorgente dati hardware Libre</a>.</p><p>Se il tuo telefono ha un <strong>chip NFC compatibile ISO 15693</strong>, puoi usare la funzione NFC di xDrip con Libre 1/14 giorni/Pro e 2/2+ (EU).</p><p>Ricordati di attivare prima la funzione NFC nelle impostazioni di Android.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_nfc_grey600_48dp.png" style="width:5%;"> Funzionalità Scansione NFC</p></div><div class="admonition xdripitem"><p class="admonition-title">Usa funzionalità NFC <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Consenti la scansione dei sensori quando l&#39;app è aperta. I dati storici saranno ripristinati. Altamente sperimentale! Attenzione che questo potrebbe rompere il sensore. Prova la compatibilità con un sensore quasi scaduto. Sei stato avvisato!</p></div><p>Puoi mostrare l&#39;età del sensore in fondo al grafico principale (xDrip master).</p><div class="admonition xdripitem"><p class="admonition-title">Età del sensore o scadenza <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Mostra l&#39;età del sensore nella schermata principale</p></div><p>Per aprire automaticamente xDrip quando viene rilevato un sensore NFC dovresti <strong>attivare</strong> Scansiona quando non in xDrip+ (consigliato). Se più app possono scansionare dispositivi NFC, a ogni scansione ti verrà chiesto quale usare.</p><div class="admonition xdripitem"><p class="admonition-title">Scansiona quando non in xDrip+ <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> La scansione NFC funzionerà anche dalla schermata di home di Android</p></div><p>Puoi decidere come xDrip ti segnalerà che la scansione è terminata. Vibrazione e suono sono utili durante le scansioni NFC (lunghe): dovresti <strong>attivarli</strong> entrambi.</p><p>Durante la scansione ricorda che devi tenere il telefono sul punto dell&#39;antenna NFC per qualche secondo per permettere una scansione corretta. Consulta la documentazione del produttore del telefono per sapere dove si trova.</p><div class="admonition xdripitem"><p class="admonition-title">Vibra per indicare lo stato della scansione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Bippa quando scansioni nell&#39;app xDrip+ <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Visibile solo con la Modalità Sviluppatore attivata.</p></div><p>La scansione più veloce è <strong>attivata</strong> per impostazione predefinita. Se hai problemi a scansionare i sensori, prova a disattivarla.</p><div class="admonition xdripitem"><p class="admonition-title">Usa il metodo più veloce di lettura multi-blocco <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Se hai problemi con l&#39;NFC del telefono, prova ad <strong>attivare</strong> il metodo any-tag.</p><div class="admonition xdripitem"><p class="admonition-title">Usa il metodo di lettura ottimizzato any-tag <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><h2 id="starting-bluetooth-connection-with-libre2-sensors" tabindex="-1">Avvio della connessione bluetooth con i sensori Libre2 <a class="header-anchor" href="#starting-bluetooth-connection-with-libre2-sensors" aria-label="Permalink to &quot;Avvio della connessione bluetooth con i sensori Libre2 {#starting-bluetooth-connection-with-libre2-sensors}&quot;">​</a></h2><p>Questa funzione permette a xDrip di prendere il controllo della connessione Bluetooth del sensore. Sulla maggior parte dei telefoni non è compatibile con l&#39;app del produttore (una sola app può connettersi allo stesso sensore). Alcuni utenti riferiscono di poter connettere contemporaneamente l&#39;app del produttore e xDrip, ma non è garantito: disinstalla l&#39;app del produttore se vuoi che xDrip sia connesso al sensore.</p><div class="admonition xdripitem"><p class="admonition-title">Avvio della connessione bluetooth con i sensori Libre2</p><p> Connettersi ai sensori Libre 2 dopo la scansione. Questo impedirà al lettore Libre e a Libre link di ricevere gli allarmi,</p></div><p>Questa scelta comparirà quando scansioni un nuovo sensore Libre 2 solo se hai selezionato Ask me every time (chiedimelo ogni volta).</p><p>Tieni presente che Connettersi sempre ai sensori Libre 2 molto probabilmente disconnetterà qualsiasi altra app o dispositivo connesso al sensore. Se xDrip si associa correttamente, non sarà più possibile recuperare la connessione dall&#39;altro dispositivo/app.</p><div class="admonition xdripitem"><p class="admonition-title">Avvio della connessione bluetooth con i sensori Libre2</p><p> Connettersi sempre ai sensori Libre 2<span style="float:right;">○ </span>   <br>  Ask me every time<span style="float:right;">● </span><br>  Non connettersi mai ai sensori Libre 2<span style="float:right;">○ </span></p></div><h2 id="smooth-libre-3-data-when-using-xxx-method" tabindex="-1">Liscia i dati libre 3 quando si usa il metodo xxx <a class="header-anchor" href="#smooth-libre-3-data-when-using-xxx-method" aria-label="Permalink to &quot;Liscia i dati libre 3 quando si usa il metodo xxx {#smooth-libre-3-data-when-using-xxx-method}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Lo smoothing si applica a qualsiasi app sorgente dati esterna che usa la sorgente dati <code>Libre2 (patched app)</code>.</p></div><p>L&#39;implementazione originale includeva un algoritmo di smoothing di 25 minuti per eliminare il rumore e rendere più sicuro il loop chiuso fai-da-te con i sensori Libre. Puoi cambiare il periodo di smoothing in 10, 15 o 25 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Liscia i dati libre 3 quando si usa il metodo xxx</p><p> Numero di minuti da prendere in considerazione quando si usano i dati librex</p></div><p>Lo smoothing aggiunge un ritardo alla glicemia di xDrip rispetto ai dati grezzi. Il ritardo è circa la metà del periodo di smoothing. Per la tua sicurezza, imposta il ritardo in base al comportamento del sensore. Se non usi un sistema di loop chiuso fai-da-te a cui xDrip fornisce i valori glicemici, impostalo su 10 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Liscia i dati libre 3 quando si usa il metodo xxx</p><p> 10 minuti<span style="float:right;">○ </span>   <br>  15 minuti<span style="float:right;">○ </span><br>  25 minuti &gt;<span style="float:right;">● </span></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',31)])])}const y=t(p,[["render",d]]);export{z as __pageData,y as default};
